import {
  IHikingUserPositionsStatDTO,
  IHikingWithFriendDTO,
} from '../@types/DTO/hikingWithFriend.dto.types';
import { IHikingUserPositionStat, IHikingWithFriend } from '../@types/hikingWithFriend.types';

export const mapHikingWithFriendToFront = (backData: IHikingWithFriendDTO): IHikingWithFriend => {
  return {
    id: +backData.id,
    name: backData.name,
    description: backData.desc,
    ava: backData.ava,
    start: new Date(+backData.start * 1000),
    finish: new Date(+backData.finish * 1000),
    type: {
      id: +backData.type,
      name: backData.type,
    },
    id_route: +backData.id_route,
    distance: +backData.distance,
  };
};

export const mapHikingUserPositionToFront = (
  backData: IHikingUserPositionsStatDTO,
): IHikingUserPositionStat => {
  return {
    id: +backData.id,
    position: {
      id: +backData.id_position,
      name: backData.position_name,
      description: backData.positions_description,
    },
    hiking: {
      id: +backData.id_hiking,
      name: backData.hiking_name,
      start: new Date(backData.hiking_start),
      finish: new Date(backData.hiking_finish),
      ava: backData.hiking_ava,
    },
    comment: backData.comment,
    date: new Date(backData.response_approve_date),
  };
};
